# Generated by Sanka. Async FastAPI over the existing SQL tables.
from contextlib import asynccontextmanager

from fastapi import Depends, FastAPI, Request
from fastapi.responses import Response

import sanka_native as native
import sanka_store as store


@asynccontextmanager
async def lifespan(_app: FastAPI):
    await store.init_db()
    try:
        yield
    finally:
        await store.close_db()


app = FastAPI(title="Sanka native FastAPI application", lifespan=lifespan)

_ACCOUNT = native.resource("ledger.views.AccountViewSet")

@app.get("/api/")
async def api_root(request: Request) -> Response:
    return await native.api_root(request, "/api/")

@app.get("/api/accounts/")
async def list_account(request: Request) -> Response:
    return await native.handle(_ACCOUNT, "list", request)

@app.post("/api/accounts/")
async def create_account(request: Request, raw_body: bytes = Depends(native.read_raw_body)) -> Response:
    return await native.handle(_ACCOUNT, "create", request, raw_body)

@app.delete("/api/accounts/{pk}/")
async def delete_account(request: Request, pk: str) -> Response:
    return await native.handle(_ACCOUNT, "destroy", request)

@app.get("/api/accounts/{pk}/")
async def get_account(request: Request, pk: str) -> Response:
    return await native.handle(_ACCOUNT, "retrieve", request)

@app.patch("/api/accounts/{pk}/")
async def update_account(request: Request, pk: str, raw_body: bytes = Depends(native.read_raw_body)) -> Response:
    return await native.handle(_ACCOUNT, "partial_update", request, raw_body)

@app.put("/api/accounts/{pk}/")
async def replace_account(request: Request, pk: str, raw_body: bytes = Depends(native.read_raw_body)) -> Response:
    return await native.handle(_ACCOUNT, "update", request, raw_body)

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=8000)
